def _sparse_line(x, y, priors):
    if not priors:
        return (1.0, np.median(y - x) if len(x) else 0.0)
    if len(x) == 0:
        return priors[0]
    a = np.asarray(priors)
    err = np.abs(y[:, None] - x[:, None] * a[:, 0] - a[:, 1])
    support = err <= 0.003
    counts = support.sum(axis=0)
    if counts.max():
        best = np.lexsort((np.minimum(err, 0.003).sum(axis=0), -counts))[0]
        return a[best]
    best = np.argmin(np.median(err, axis=0))
    g, b = a[best]
    offsets = y - g * x
    middle = np.median(offsets)
    if len(x) >= 2 and np.count_nonzero(np.abs(offsets - middle) < 0.003) > len(x) / 2:
        b = middle
    return (g, b)

def _fit(x, h, p, dt, t, threshold, y, rate):
    from scipy.optimize import least_squares
    yc, yr = (np.isfinite(y), np.isfinite(rate))
    obs = np.r_[y[yc], rate[yr]]
    rate_start = yc.sum()

    def decode(v):
        return np.array([v[0], v[0] + (24.99 - v[0]) * v[1]])

    def design(v):
        curves, rates = _design(decode(v), x, h, p, dt, t, threshold)
        return np.vstack((curves[yc], rates[yr]))

    def profile(v, w):
        a = design(v)
        coef = np.linalg.lstsq(a * w[:, None], obs * w, rcond=1e-10)[0]
        return (a @ coef - obs, coef)

    def opt(v, w):
        return least_squares(lambda q: w * profile(q, w)[0], v, bounds=([0.0501, 1e-05], [24.0, 0.99999]), ftol=1e-10, max_nfev=80)

    def spread(r):
        return max(0.0001, 1.4826 * np.median(np.abs(r - np.median(r)))) if r.size else 1.0
    w = np.ones(len(obs))
    starts = [(a, (b - a) / (24.99 - a)) for a, b in ((0.2, 1.4), (0.5, 2.8), (1.2, 5.0), (2.5, 10.0))]
    v = min((opt(start, w) for start in starts), key=lambda r: r.cost).x
    for i in range(6):
        r, coef = profile(v, w)
        sc = spread(r[:rate_start])
        sr = spread(r[rate_start:])
        base = np.r_[np.full(rate_start, sc), np.full(len(obs) - rate_start, sr)]
        w = 1.0 / base / np.hypot(1.0, r / (3.0 * base))
        w /= np.max(w)
        v = opt(v, w).x
    theta = profile(v, w)[1]
    if not np.any(np.abs(h) > threshold):
        theta[7] = 0.0
    if not np.any(np.abs(p) > threshold):
        theta[8] = 0.0
    return (decode(v), theta)

def coeff(ix, s, u):
    ok = ix & np.isfinite(s) & np.isfinite(u)
    if ok.sum() < 6:
        return 0.0
    v = u[ok]
    y = s[ok]
    return np.clip(np.mean(v * y) / max(np.mean(v * v), 1e-12), 0.0, 1.0)

def apply(k, lab, complete, u):
    w = np.where(complete, np.asarray(k)[lab // 2], k[2])
    return w * np.nan_to_num(u)

def _crossing(tau, amplitude, drift, threshold, end):
    """First upward crossing of the continuous two-mode trajectory."""
    from scipy.optimize import brentq
    if threshold <= 0.0:
        return 0.0
    inv = 1.0 / tau
    rates = amplitude * inv

    def level(t):
        return -np.expm1(-t * inv) @ amplitude + drift * t - threshold

    def slope(t):
        return np.exp(-t * inv) @ rates + drift
    curvature = rates * inv
    breaks = [0.0, end]
    if np.sign(curvature[0]) * np.sign(curvature[1]) < 0:
        pivot = (np.log(abs(curvature[0])) - np.log(abs(curvature[1]))) / (inv[0] - inv[1])
        if 0.0 < pivot < end:
            breaks.insert(1, pivot)
    extrema = [0.0]
    for a, b in zip(breaks[:-1], breaks[1:]):
        sa, sb = (slope(a), slope(b))
        if sa * sb < 0.0:
            extrema.append(brentq(slope, a, b))
        elif sb == 0.0 and b < end:
            extrema.append(b)
    for a, b in zip(extrema, extrema[1:] + [end]):
        if level(b) >= 0.0:
            return brentq(level, a, b)
    return end
